// Jo's agreed sample replies (29 Oct 2026), verbatim. Each must pass the AI reply rules.
export type AiReplySample = { id: number; preRelease: boolean; body: string };

export const AI_REPLY_SAMPLES: AiReplySample[] = [
  { id: 1, preRelease: true, body: "Hi Bryan,\n\nThanks for asking, and I'm sorry this isn't the answer you were hoping for. We don't offer a payment plan. We pay the installer, the electrician and the product costs as each step happens, so we can't carry the cost for you.\n\nTo make it easier, the payments are spread out: $349 for the electrical safety check (PIESA), then 10% to book your install, then the rest on install day. Nothing is due now, and your spot stays saved.\n\nCheers, the Home Insulation Victoria team" },
  { id: 2, preRelease: true, body: "Hi Margaret,\n\nThank you for being so open with us. I'm really sorry, I know $2,718 is a lot, especially with your hot water system to replace too.\n\nThe $980 rebate is the same for every home, and it's the biggest help we're able to give. We don't have an extra discount for concession cards, and there's no need to send yours in.\n\nYour spot stays saved and there's no pressure at all. If now isn't the right time, that's completely fine. Just reply whenever you're ready.\n\nCheers, the Home Insulation Victoria team" },
  { id: 3, preRelease: true, body: "Hi Mariano,\n\nThanks for letting us know, and I understand wanting to make sure you're getting a fair price.\n\nSome quotes are cheaper because they don't include everything a rebate job has to. Your price includes:\n- an electrical safety check (PIESA) by a licensed electrician before any insulation goes in ($349), which finds wiring and downlight hazards in the ceiling\n- a certified installer and an approved product that meets the Australian standard\n- our Accredited Person fee ($349), which covers checking everyone's licence and insurance, the evidence, and your rebate claim\n\nIf another quote doesn't include these, the job may not qualify for the rebate, and you'd be taking on the electrical safety risk. You're very welcome to compare, and your spot stays saved if you'd like to go ahead.\n\nCheers, the Home Insulation Victoria team" },
  { id: 4, preRelease: true, body: "Hi John,\n\nThanks for offering your certificate. Unfortunately we can't use it, because the government's rebate rules for the electrical safety check (PIESA) are strict. It has to be:\n- done by an electrician working under a Registered Electrical Contractor (REC)\n- by an electrician whose $5 million insurance we've checked and approved\n- done within 30 days of the install\n\nA check from a couple of months ago won't meet those rules, so a new one is needed for your rebate.\n\nR6.0 batts are no problem. You'll see the exact price before you agree to anything.\n\nCheers, the Home Insulation Victoria team" },
  { id: 6, preRelease: true, body: "Hi Mohamed,\n\nThanks for the extra detail, that really helps.\n- R7: yes, we offer R7.0. For 90 m² it's $3,008 after the $840 rebate ($3,848 before), including GST. When it's your turn, please let your installer know you'd like R7.0 at your free Ready Check. I've also added a note to your job for them.\n- Existing insulation: for the rebate, what's there now has to be below R2.0. The installer checks this at the Ready Check, before you agree to anything.\n- Wait time: We're bringing on more and more certified installers, but demand is high and there aren't enough of them yet. So we're booking people in the order they saved their spot, as quickly as we can bring on more CII-certified installers. We can't give a date yet, but we'll be in touch as soon as your spot is released.\n\nCheers, the Home Insulation Victoria team" },
  { id: 8, preRelease: true, body: "Hi Jayden,\n\nThanks for your patience, and sorry we can't be more exact. We're bringing on more and more certified installers, but demand is high and there aren't enough of them yet. So we're booking people in the order they saved their spot, as quickly as we can bring on more CII-certified installers. We can't give a date yet, but we'll be in touch as soon as your spot is released.\n\nYour spot is saved and you don't need to do anything.\n\nCheers, the Home Insulation Victoria team" },
  { id: 9, preRelease: true, body: "Hi Merav,\n\nThanks for following up, and I'm sorry for the wait. We've had thousands of enquiries.\n\nYour estimate is ready, but your spot isn't saved yet. Saving it is free, with no obligation:\n\nhttps://estimate.homeinsulationvictoria.com.au/estimate/TOKEN/campaign\n\nHere's how it works. Spots are released in the order they were saved. When yours is released, it's your turn: a certified installer will text and email you some times for your free Ready Check. They measure your ceiling and check your insulation, then you get your final price before you agree to anything.\n\nCheers, the Home Insulation Victoria team" },
  { id: 14, preRelease: false, body: "Hi Greg,\n\nThanks for asking. The electrician found a few things in your ceiling that aren't safe to cover with insulation, so they need fixing before the install. These are your electrical upgrades, quoted separately.\n\nTiming matters. Under the government's rebate rules, your electrical safety check (PIESA) is only valid for 30 days before your install. After that, a new one is needed, at another $349.\n\nYour own electrician can do the upgrades if they can:\n- show us they work under a Registered Electrical Contractor (REC)\n- give us proof of $5 million public liability insurance, which we approve\n- do the work, and get the Certificate of Electrical Safety (COES) and our forms signed and back to us, before your 30 days run out\n\nIf that works for them, they can sign up here:\n\nhttps://portal.homeinsulationvictoria.com.au/electrician-onboarding\n\nIf not, our electrician can do it and we'll keep everything on time for you.\n\nCheers, the Home Insulation Victoria team" },
  { id: 15, preRelease: true, body: "Hi Mariano,\n\nThanks for telling us, and I'm sorry it's come across that way. I'd like to explain exactly what you're paying for, because a rebate job has to be done properly.\n\nSafety first. Under the government's rebate rules, a licensed electrician does an electrical safety check (PIESA) in your ceiling before any insulation goes in. They look for faulty wiring and downlights that could overheat or start a fire under insulation. Many cheaper quotes skip this.\n\nQualified people. Your installer is CII-certified, and the electrician works under a Registered Electrical Contractor. We check every licence and every $5 million insurance policy before they set foot in your home.\n\nQuality product. Approved batts that meet the Australian standard, at the R-value you're quoted, so your home actually stays cooler in summer and warmer in winter.\n\nWe do the paperwork. As the Accredited Person, we check all the evidence and claim the rebate for you. It comes off your price upfront, so you don't wait for money back.\n\nCheaper quotes often leave out the safety check, use uncertified workers, or can't give you the rebate. You're welcome to compare, and there's no obligation to go ahead with us. If you do, your spot is saved.\n\nCheers, the Home Insulation Victoria team" },
  { id: 23, preRelease: true, body: "Hi Robert,\n\nThanks for looking into it. Older insulation often is below R2.0, so you may well qualify. But under the government's rebate rules it has to be checked in your ceiling. Age alone isn't enough.\n\nYou don't need to go into the roof or send photos. When your spot is released, your installer checks it at your free Ready Check, and you'll know before you agree to anything.\n\nCheers, the Home Insulation Victoria team" },
];
